        // Declared native-host adapter over its independent real Range loader.
        // Uses source built-in candidates; no fabricated safe/loaded result.
        sealed class RangeWorld:IR24LanSpawnWorld
        {
            readonly R23PlayableMap loaded,represented;readonly Collider[] hits=new Collider[64];public RangeWorld(R23PlayableMap loaded,R23PlayableMap represented){this.loaded=loaded;this.represented=represented;}
            public bool ReadyForSpawn(string map,bool warmup){return loaded.IsLoaded&&represented.IsLoaded&&map=="range"&&loaded.ManifestSha256==represented.ManifestSha256;}
            Vector3 ToLoaded(Vector3 p){return loaded.transform.TransformPoint(represented.transform.InverseTransformPoint(p));}Vector3 FromLoaded(Vector3 p){return represented.transform.TransformPoint(loaded.transform.InverseTransformPoint(p));}
            public SpawnSite[] Sites(string map,bool warmup){var rows=new List<SpawnSite>();if(!ReadyForSpawn(map,warmup)||warmup)return rows.ToArray();for(int i=0;i<8;i++){var at=ToLoaded(V(R24LanSpawnCoordinates.BuiltinArena(F(represented.GameSpawn),i)));RaycastHit hit;if(Physics.Raycast(at+Vector3.up*20,Vector3.down,out hit,50,1<<0,QueryTriggerInteraction.Ignore)&&hit.collider.transform.IsChildOf(loaded.transform)&&hit.normal.y>=.65f)rows.Add(new SpawnSite("actual-range:"+i,F(FromLoaded(hit.point+Vector3.up*.2f)),-1,false,false));}return rows.ToArray();}
            public bool IsSafe(string map,string actor,Float3 p){if(!ReadyForSpawn(map,false)||!p.IsFinite)return false;var at=ToLoaded(V(p));RaycastHit floor;if(!Physics.Raycast(at+Vector3.up*.3f,Vector3.down,out floor,.8f,1<<0,QueryTriggerInteraction.Ignore)||!floor.collider.transform.IsChildOf(loaded.transform)||floor.normal.y<.65f)return false;float height=Ashfall.Integration.Playable.Calibration.R23CalibrationState.TargetHeadTop+.10f;int n=Physics.OverlapCapsuleNonAlloc(at+Vector3.up*.29f,at+Vector3.up*(height-.27f+.02f),.27f,hits,(1<<0)|(1<<8),QueryTriggerInteraction.Ignore);Array.Clear(hits,0,hits.Length);return n==0;}
        }
        IEnumerator ClientRound()
