            end=Time.realtimeSinceStartup+15;while(Time.realtimeSinceStartup<end){Frame();if(root.Gameplay.PlayerHealthViewBound&&root.Gameplay.LocalMatchHealth!=null&&!root.UI.AuthoritativeHealthPending&&!root.LanSession.MapEntryBlocked)break;yield return null;}VerifyPlacement(owned.Lobby);Need(root.LanRoundBound&&root.MatchActive&&root.Gameplay.Health==90&&root.Gameplay.Shield==20&&current.missingHealthFrames>0,"Actual client round arrives from host Health, not local start values");
